#!/usr/bin/env bash
# Vendors @walletconnect/sign-client/v3 into both apps, at src/lib/sign-client-v3: one
# self-contained ESM bundle (the Sign v3 WASM embedded, every dependency inlined) and its types.
# The apps then build from source, with no npm package for the client.
#
# Build sign-client first, in walletconnect-monorepo: npm run build -w @walletconnect/sign-client
# MONOREPO_DIR defaults to a walletconnect-monorepo checkout next to web-examples.
set -euo pipefail

here=$(cd "$(dirname "$0")/.." && pwd)
mono=$(cd "${MONOREPO_DIR:-$here/../../walletconnect-monorepo}" && pwd)
pkg=$mono/packages/sign-client
[ -f "$pkg/dist/v3/index.js" ] || { echo "no $pkg/dist/v3: build sign-client first" >&2; exit 1; }

rev=$(git -C "$mono" rev-parse --short HEAD)
git -C "$mono" diff --quiet HEAD -- packages/sign-client || rev="$rev+local"
engine=$(grep -o 'yttrium [0-9a-f]*[+a-z]*' "$pkg/dist/v3/index.js" | head -1)
banner="// @walletconnect/sign-client/v3 from walletconnect-monorepo $rev, engine $engine. Generated by v3/scripts/vendor-sign-client.sh; don't edit."

for app in dapp wallet; do
  out=$here/$app/src/lib/sign-client-v3
  rm -rf "$out"
  mkdir -p "$out/wasm"
  "$mono/node_modules/.bin/esbuild" "$pkg/dist/v3/index.js" --bundle --minify --platform=browser \
    --format=esm --target=es2022 --banner:js="$banner" --outfile="$out/index.js" --log-level=warning
  cp "$pkg/dist/types/v3/index.d.ts" "$pkg/dist/types/v3/client.d.ts" "$out/"
  cp "$pkg/dist/types/v3/wasm/wasm-data.d.ts" "$out/wasm/"
  # The Community License travels with redistributed copies, with this notice.
  cp "$pkg/LICENSE.md" "$out/LICENSE.md"
  printf '%s\n\n%s\n' "Portions © 2025 Reown, Inc. All Rights Reserved" \
    "This folder is a build of @walletconnect/sign-client/v3, licensed under the WalletConnect Community License in LICENSE.md." \
    >"$out/NOTICE.md"
  # The declaration maps point into the monorepo; drop their references.
  sed -i.bak '/^\/\/# sourceMappingURL=/d' "$out"/*.d.ts "$out"/wasm/*.d.ts && rm -f "$out"/*.bak "$out"/wasm/*.bak
  echo "vendored $out: $(wc -c <"$out/index.js" | tr -d ' ') bytes"
done
echo "monorepo $rev, engine $engine"
